import { AriaLive } from './search.a11y';

const speakTimeout = 300;
const cleanupTimeout = 1000;

/**
 * Adds styles to HTML elements following the Accessible Hiding CSS specification.
 * https://a11y-guidelines.orange.com/en/web/components-examples/accessible-hiding/index.html
 */
const applyHidingStyle = (el: HTMLElement) => {
    el.style.position = 'absolute';
    el.style.width = '1px';
    el.style.height = '1px';
    el.style.padding = '0';
    el.style.margin = '-1px';
    el.style.overflow = 'hidden';
    el.style.whiteSpace = 'nowrap';
    el.style.border = '0';
};

/**
 * Makes the screen reader speak the provided message.
 * https://a11y-guidelines.orange.com/en/web/components-examples/make-a-screen-reader-talk/
 */
export const speak = (msg: string, priority?: AriaLive) => {
    const el = document.createElement('div');
    el.setAttribute('role', 'alert');
    el.setAttribute('aria-live', priority || 'polite');

    applyHidingStyle(el);

    document.body.appendChild(el);

    setTimeout(() => {
        el.innerHTML = msg;
    }, speakTimeout);

    setTimeout(() => {
        document.body.removeChild(el);
    }, cleanupTimeout);
};
